function open(){return new Promise((resolve,reject)=>{const r=indexedDB.open('qinghe-school',1);r.onupgradeneeded=()=>r.result.createObjectStore('saves');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function saveGame(value){const db=await open();return new Promise((resolve,reject)=>{const t=db.transaction('saves','readwrite');t.objectStore('saves').put({value,at:Date.now()},'manual');t.oncomplete=()=>{db.close();resolve();};t.onerror=()=>{db.close();reject(t.error);};});}
export async function loadGame(){const db=await open();return new Promise((resolve,reject)=>{const r=db.transaction('saves').objectStore('saves').get('manual');r.onsuccess=()=>{db.close();resolve(r.result?.value||null);};r.onerror=()=>{db.close();reject(r.error);};});}
